mapper.select:
select tag.tag_id, tag.tag_name, rel.id, rel.alarm_type_id, rel.type_value, if(rel.alarm_type_id is null,0,1) is_rel from sys_alarm_tags tag left join sys_alarm_tags_type_rel rel on tag.tag_id = rel.tag_id
and rel.type_value = #{alarmTypeId}
and rel.type_value in
#{alarmTypeId}
and exists (SELECT 1 from sys_alarm_type sat where sat.type_value=rel.type_value) and rel.delete_flag = '0' where tag.delete_flag = '0' and tag.tenant_id = #{tenantId}
and tag.industry_code = #{industryCode}
order by tag.create_time

select tag.tag_id, tag.tag_name, sat.type_value, sat.type_name
from sys_alarm_tags_type_rel rel
inner join sys_alarm_type sat on sat.type_value = rel.type_value
inner join sys_alarm_tags tag on tag.tag_id = rel.tag_id
where tag.delete_flag = '0' and rel.delete_flag = '0' and sat.delete_flag = '0'
and tag.tenant_id = #{tenantId}
and tag.industry_code = #{industryCode}
and rel.type_value in

    #{item}

${dataScope}
order by tag.create_time, tag.tag_id

mapper.delete:
DELETE FROM sys_alarm_tags_type_rel t
WHERE t.delete_flag = '0'
and t.tenant_id = #{tenantId}
and t.alarm_type_id = #{alarmTypeId}

    and exists (SELECT 1 from sys_alarm_tags a where a.tag_id = t.tag_id and a.tenant_id = t.tenant_id and a.industry_code = #{industryCode} )

DELETE FROM sys_alarm_tags_type_rel t
WHERE t.delete_flag = '0'
and t.tenant_id = #{tenantId}
and t.alarm_type_id in

    #{alarmTypeId}


    and exists (SELECT 1 from sys_alarm_tags a where a.tag_id = t.tag_id and a.tenant_id = t.tenant_id and a.industry_code = #{industryCode} )
